<?php

declare(strict_types=1);

namespace App\Hosts\Protocol;

use App\Attributes\AutoGenerated;
use App\Hosts\Enums\HostProcessType;

/**
 * Every order of host protocol 1, the whole vocabulary a host carries out.
 * Generated by php artisan journal:host-protocol from protocol/host.json; do not edit.
 */
#[AutoGenerated('protocol/host.json')]
enum HostOrderType: string
{
    case OpenContainer = 'open_container';
    case OpenProcess = 'open_process';
    case WriteKeys = 'write_keys';
    case WriteStdin = 'write_stdin';
    case CloseStdin = 'close_stdin';
    case OpenPrivate = 'open_private';
    case WritePrivate = 'write_private';
    case ClosePrivate = 'close_private';
    case Resize = 'resize';
    case Signal = 'signal';
    case Stop = 'stop';
    case Stream = 'stream';
    case Snapshot = 'snapshot';
    case RunFenced = 'run_fenced';
    case AllowImages = 'allow_images';
    case MakeFolder = 'make_folder';
    case RemoveFolder = 'remove_folder';
    case FolderUse = 'folder_use';
    case Remove = 'remove';
    case ReadProject = 'read_project';
    case Record = 'record';
    case StopRecording = 'stop_recording';
    case Upgrade = 'upgrade';

    /**
     * Whether the order ends its process, so a process that ended still lets its host answer it.
     */
    public function endsProcess(): bool
    {
        return in_array($this, [self::Stop, self::Remove], true);
    }

    public function isInput(): bool
    {
        return in_array($this, [self::WriteKeys, self::WriteStdin, self::CloseStdin, self::WritePrivate], true);
    }

    /**
     * Whether a claim of this order cut off by the host's restart is offered to the new process:
     * never an input, which is never written twice, nor an order the journal gives anew after a
     * restart.
     */
    public function isOfferedAgainAfterRestart(): bool
    {
        return ! in_array($this, [
            self::WriteKeys,
            self::WriteStdin,
            self::CloseStdin,
            self::WritePrivate,
            self::AllowImages,
        ], true);
    }

    /**
     * Whether this order opens a process, so its payload carries the process's environment.
     */
    public function isOpening(): bool
    {
        return in_array($this, [self::OpenContainer, self::OpenProcess], true);
    }

    /**
     * Whether this order can be carried out on a process of that type: keys and screens need a terminal,
     * standard input needs pipes.
     */
    public function suits(HostProcessType $type): bool
    {
        return match (true) {
            in_array($this, [
                self::WriteKeys,
                self::Resize,
                self::Stream,
                self::Snapshot,
            ], true) => $type === HostProcessType::Terminal,
            in_array($this, [self::WriteStdin, self::CloseStdin], true) => $type === HostProcessType::Pipe,
            default => true,
        };
    }
}
